style.css:
/* Change background color to black and text color to white */
body {
    background-color: black !important; /* Set background to black */
    color: white !important;            /* Set text color to white */
}

/* Change all links to bold */
a {
    font-weight: bold !important;       /* Make links bold */
}

/* Remove space between lines of text (line height) */
* {
    line-height: 1 !important;          /* Set line height to 1.5 */
    margin: 0 !important;               /* Remove margin */
    padding: 0 !important;              /* Remove padding */
}

/* Additionally, ensure paragraphs and headers don't add extra space */
p, h1, h2, h3, h4, h5, h6 {
    margin: 0 !important;               /* Remove margins */
    line-height: 1 !important;          /* Set line height */
}
